  if cleaned == "/" || strings.HasPrefix(cleaned, "/..") {
    return "", fmt.Errorf("scp: key %q escapes root", prefix)
  }
  full := path.Join(p.root, cleaned)
  rel, err := filepath.Rel(p.root, full)
  if err != nil || strings.HasPrefix(rel, "..") {
